          "col_widths"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_rectangle",
      "category": "draw",
      "description": "Draw an axis-aligned (optionally rotated) rectangle as a closed polyline. Give either 'corner' (lower-left) or 'center'.",
      "params": {
        "type": "object",
        "properties": {
          "corner": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Lower-left corner [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Center point [x, y] (drawing units, or string with unit e.g. '8mm')"
